import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix, env=None):
    if env is None:
        env = os.environ
    config = defaults.copy()
    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(toml_config)
        except FileNotFoundError:
            pass
    for key, value in env.items():
        if key.startswith(env_prefix):
            env_key = key[len(env_prefix):].replace('__', '.').lower()
            env_value = _coerce_value(env_key, value, config)
            _set_nested_key(config, env_key, env_value)
    return config

def _coerce_value(key, value, config):
    default_value = _get_nested_key(config, key)
    if isinstance(default_value, int):
        return int(value)
    elif isinstance(default_value, float):
        return float(value)
    elif isinstance(default_value, bool):
        return value.lower() in ['true', '1', 'yes']
    elif isinstance(default_value, str):
        return value
    else:
        raise ConfigError(f'Unsupported type for key {key}')

def _set_nested_key(d, key, value):
    keys = key.split('.')
    for k in keys[:-1]:
        if k not in d:
            d[k] = {}
        d = d[k]
    d[keys[-1]] = value

def _get_nested_key(d, key):
    keys = key.split('.')
    for k in keys:
        if k not in d:
            raise ConfigError(f'Missing key {key}')
        d = d[k]
    return d

