import pytest
from envcfg import load_config, ConfigError

def test_precedence_order():
    defaults = {'a': 1, 'b': 2}
    toml_config = {'b': 3}
    env_config = {'APP_A': '4'}
    config = load_config(defaults, toml_path='config.toml', env_prefix='APP', env=env_config)
    assert config == {'a': 4, 'b': 3}

def test_nested_overrides():
    defaults = {'server': {'port': 8080}}
    toml_config = {'server': {'port': 8081}}
    env_config = {'APP_SERVER_PORT': '8082'}
    config = load_config(defaults, toml_path='config.toml', env_prefix='APP', env=env_config)
    assert config == {'server': {'port': 8082}}

def test_coercion_types():
    defaults = {'a': 1, 'b': 2.0, 'c': True, 'd': 'hello'}
    env_config = {'APP_A': '2', 'APP_B': '3.0', 'APP_C': 'false', 'APP_D': 'world'}
    config = load_config(defaults, env_prefix='APP', env=env_config)
    assert config == {'a': 2, 'b': 3.0, 'c': False, 'd': 'world'}

def test_error_cases():
    defaults = {'a': 1, 'b': 2.0, 'c': True, 'd': 'hello'}
    env_config = {'APP_A': 'two', 'APP_B': 'three', 'APP_C': 'yes', 'APP_D': '42'}
    with pytest.raises(ConfigError):
        load_config(defaults, env_prefix='APP', env=env_config)

def test_missing_file():
    defaults = {'a': 1}
    config = load_config(defaults, toml_path='nonexistent.toml', env_prefix='APP')
    assert config == {'a': 1}

